#!/usr/bin/env python3
"""Debug script to trace the exact error in get_k8s_client_from_content"""
import sys
import traceback
import tempfile
import os
sys.path.insert(0, '/app/backend')
from kubernetes import client, config

# Simulate the kubeconfig with docker-desktop context (inline cert data)
# Using a minimal kubeconfig that mirrors the actual one
KUBECONFIG = """apiVersion: v1
clusters:
- cluster:
    insecure-skip-tls-verify: true
    server: https://kubernetes.default.svc.cluster.local:443
  name: docker-desktop
- cluster:
    certificate-authority: /nonexistent/path/ca.crt
    server: https://127.0.0.1:63624
  name: minikube
contexts:
- context:
    cluster: docker-desktop
    user: docker-desktop
  name: docker-desktop
- context:
    cluster: minikube
    user: minikube
  name: minikube
current-context: docker-desktop
kind: Config
users:
- name: docker-desktop
  user:
    client-certificate-data: 
    client-key-data: 
- name: minikube
  user:
    client-certificate: /nonexistent/minikube/client.crt
    client-key: /nonexistent/minikube/client.key
"""

print("Testing kubeconfig loading with docker-desktop context...")
try:
    tf = tempfile.NamedTemporaryFile(mode='w', suffix='.kubeconfig', delete=False)
    tf.write(KUBECONFIG)
    tf.close()
    print(f"Temp file: {tf.name}")
    
    config.load_kube_config(config_file=tf.name, context='docker-desktop')
    v1 = client.CoreV1Api()
    print("SUCCESS: Kubernetes client created")
    
except Exception as e:
    print(f"ERROR: {type(e).__name__}: {e}")
    traceback.print_exc()
finally:
    try:
        os.unlink(tf.name)
    except:
        pass

print("Done.")
